const resources = Object.fromEntries(
  Object.entries(languageCodes).map(([language, code]) => [
    code,
    { translation: translations[language] || {} },
  ]),
);

i18n.init({
  resources,
  lng: "en",
  // Keep a meaningful English sentence available while a component is being
  // translated incrementally. Returning an i18n key in the UI is never useful.
  fallbackLng: "en",
  returnEmptyString: false,
  interpolation: { escapeValue: false },
  initImmediate: false,
});

function getStoredPreferences() {
  try {
    return JSON.parse(localStorage.getItem("ledgrace_profile_preferences") || "{}");
  } catch {
    return {};
  }
}

export function getStoredLanguage() {
  const selected = getStoredPreferences().language;
  if (selected && SUPPORTED_LANGUAGES.includes(selected)) return selected;

  const browserCode = window.navigator?.languages?.[0] || window.navigator?.language || "";
  const browserLanguage = Object.entries(languageCodes).find(([, code]) =>
    browserCode.toLowerCase().startsWith(code.toLowerCase()),
  )?.[0];
  return browserLanguage || "English";
}

export function getLanguageCode(language) {
  return languageCodes[language] || languageCodes.English;
}

export function translate(key, language = getStoredLanguage()) {
  const selectedLanguage = SUPPORTED_LANGUAGES.includes(language) ? language : getStoredLanguage();
  return i18n.getFixedT(getLanguageCode(selectedLanguage))(key) || key;
}

export function applyLanguage(language, options = {}) {
  const { announce = true } = options;
  const selected = language && SUPPORTED_LANGUAGES.includes(language) ? language : getStoredLanguage();
  const code = languageCodes[selected] || languageCodes.English;

  try {
    const stored = getStoredPreferences();
    const next = { ...stored, language: selected };
    localStorage.setItem("ledgrace_profile_preferences", JSON.stringify(next));
    if (announce) {
      window.dispatchEvent(new CustomEvent("ledgrace:preferences-changed", { detail: { ...next, changedKey: "language" } }));
    }
  } catch {
    // keep app functional even if storage is unavailable
  }

  document.documentElement.lang = code;
  document.documentElement.dir = code === "ar" ? "rtl" : "ltr";
  document.documentElement.classList.toggle("is-rtl", code === "ar");
  document.body?.setAttribute("data-lang", code);
  window.__ledgrace_language = selected;
  i18n.changeLanguage(code);
}

export function initializeTranslation() {
  const initialLanguage = getStoredLanguage();
  const initialCode = languageCodes[initialLanguage] || languageCodes.English;
  i18n.changeLanguage(initialCode);
  document.documentElement.lang = initialCode;
  document.documentElement.dir = initialCode === "ar" ? "rtl" : "ltr";
  document.documentElement.classList.toggle("is-rtl", initialCode === "ar");
  document.body?.setAttribute("data-lang", initialCode);
  window.__ledgrace_language = initialLanguage;

  window.addEventListener("ledgrace:preferences-changed", (event) => {
    if (event.detail?.changedKey && event.detail.changedKey !== "language") return;
    const language = event.detail?.language || getStoredLanguage();
    if (language && SUPPORTED_LANGUAGES.includes(language) && language !== window.__ledgrace_language) {
      applyLanguage(language, { announce: false });
    }
  });
}

export { i18n };
